UPDATE orders SET order_status=#{status}
,finish_time=#{finishTime}
WHERE order_id=#{id} AND order_status=#{oldStatus}

mapper.select:
SELECT  FROM orders
AND order_status=#{status}
ORDER BY create_time DESC,order_id DESC LIMIT #{size} OFFSET #{offset}

SELECT e.eva_id AS evaluate_id,e.order_id,o.goods_id,o.buyer_id AS evaluate_user_id,e.score,
  e.content AS evaluate_content,e.eva_time AS evaluate_time
FROM evaluate e JOIN orders o ON o.order_id=e.order_id WHERE e.eva_id=#{id}
